using System;
using System.Collections.Generic;
using System.Linq;
using System.Reflection;
using RainbowLi;
public static class EnemyEncounterChecks {
 static int checks;
 static void Check(bool ok,string message){checks++;if(!ok)throw new Exception(message);}
 static object Call(ContainmentGame game,string name,params object[] args)=>typeof(ContainmentGame).GetMethod(name,BindingFlags.Instance|BindingFlags.NonPublic).Invoke(game,args);
 static EncounterEffect E(EncounterOperation operation,int amount=1,EncounterTarget target=EncounterTarget.Self)=>new EncounterEffect {Operation=operation,Amount=amount,Target=target};
 static EncounterSkill Skill(string slot,params EncounterEffect[] effects)=>new EncounterSkill {Slot=slot,Name=slot,Description=slot,NumberMin=2,NumberMax=5,Weight=80,Effects=effects};
 static EncounterDefinition Definition(bool boss=false)=>new EncounterDefinition {Id="fixture",Title="Authored fixture",Boss=boss,Health=100,ActionMin=2,ActionMax=3,AttackMin=7,AttackMax=11,Skills=new[]{Skill("base",E(EncounterOperation.Damage,3,EncounterTarget.Opponent))},Sequences=new[]{new EncounterSequence {Slot="s1",Name="compound sequence",Description="shield and poison",RequiredNumber=4,Effects=new[]{E(EncounterOperation.Shield,4),E(EncounterOperation.Poison,2,EncounterTarget.Opponent)}}}};
 static GameSetup Setup(EncounterDefinition definition){var s=new GameSetup {PlayerHealth=1000};for(int i=0;i<6;i++)s.InitialDeck.Add(new Card {Number=i+1,Effect=CardEffect.Guard,BaseBonus=0});if(definition.Boss)s.BossEncounters.Add(definition);else s.NormalEncounters.Add(definition);return s;}
 static ContainmentGame Start(EncounterDefinition definition,int seed=42){var g=new ContainmentGame(seed,Setup(definition));g.Victories=6;g.StartBattle(definition.Boss);return g;}
 static void Plan(ContainmentGame g){g.AddCard(g.Hand[0]);Check(g.Confirm(),"confirm authored encounter");}
 static void Round(ContainmentGame g){Plan(g);int round=g.Round,budget=0;while(g.Phase==GamePhase.Resolving&&g.Round==round&&budget++<6000)g.Step();Check(budget<6000,"round chain terminates");}
 static void Kill(ContainmentGame g){g.EnemyHealth=1;g.Hand[0].Effect=CardEffect.Strike;g.Hand[0].BaseBonus=10000;Check(g.InsertCard(g.Hand[0],0),"insert finisher");Plan(g);while(g.Phase==GamePhase.Resolving)g.Step();}
 public static void Main(){checks=0;
  var d=Definition();var g=Start(d);Check(g.EnemyHealth==100&&g.EnemyName.StartsWith(d.Title),"authored health and title");Check(g.Enemy.Encounter.BaseAttack>=7&&g.Enemy.Encounter.BaseAttack<=11,"attack roll range");Check(g.Timeline.Count>=2&&g.Timeline.Count<=3&&g.Timeline.All(a=>a.Number>=2&&a.Number<=5),"action count and skill number ranges");Check(g.Enemy.ActiveRules.Single().Numbers.Contains(4),"required sequence number");
  d.Skills[0].Effects[0].Amount=999;Check(g.Enemy.Encounter.Definition.Skills[0].Effects[0].Amount==3,"authoring isolation");
  g.PlayerRules.Clear();g.ArenaRules.Clear();g.ArenaRules.Add(ContainmentGame.Rule("non-match",new[]{6,6,6},RuleEffect.Damage,0));
  var action=new BattleAction {Enemy=true,EncounterEffects=new[]{E(EncounterOperation.Heal,5),E(EncounterOperation.Poison,7)},EncounterDescription="self poison"};g.EnemyHealth=50;
  Call(g,"ApplyEncounterEffects",action,action.EncounterEffects,BattleEventSource.EnemySkill);Check(g.EnemyHealth==55&&g.Enemy.Statuses[CardEffect.Poison]==7&&g.Player.Statuses[CardEffect.Poison]==0,"compound effects and explicit self target");
  Check(CardEffectTargeting.TargetsEnemy(action),"authored self-target effects animate toward the enemy");Check(!CardEffectTargeting.TargetsEnemy(new BattleAction {Enemy=true,EncounterEffects=new[]{E(EncounterOperation.Poison,3,EncounterTarget.Opponent)}}),"authored opponent effects animate toward the player");
  var fractional=new EncounterEffect {UsesAttack=true,Multiplier=1.5f};Check(fractional.Resolve(7)==10,"fractional attacks floor once");
  var special=Skill("threshold",E(EncounterOperation.Shield,2));special.Special=true;special.Trigger=EncounterTrigger.HealthThreshold;special.ThresholdPercent=50;
  var follow=Skill("follow",E(EncounterOperation.Heal,2));follow.Special=true;follow.Trigger=EncounterTrigger.UsedSkill;follow.RequiredSkill="threshold";
  d=Definition();d.Skills=new[]{d.Skills[0],special,follow};g=Start(d);g.EnemyHealth=50;Plan(g);g.Step();Check(g.Timeline.Count(a=>a.EncounterSlot=="threshold")==1,"health threshold adds special once");
  while(g.Phase==GamePhase.Resolving)g.Step();Check(g.Enemy.Encounter.Unlocked.Contains("follow"),"using prerequisite unlocks follow-up");
  Check(g.Timeline.Count(a=>a.Special)<=1,"later random pool contains at most one special");
  d=Definition(true);d.Phases=new[]{new EncounterPhase {Index=0,Passives=new[]{new EncounterPassive {Timing=EncounterTiming.RoundStart,Effects=new[]{E(EncounterOperation.Shield,5)}}}},new EncounterPhase {Index=1,ThresholdPercent=60,Label="phase one",Passives=new[]{new EncounterPassive {Timing=EncounterTiming.FirstOwnActionAfter,Effects=new[]{new EncounterEffect {Operation=EncounterOperation.FillNumber,Amount=1,NumberMode=EncounterNumber.Any}}}}}};
  var periodic=Skill("periodic",E(EncounterOperation.Invulnerable));periodic.Special=true;periodic.FixedTrigger=true;periodic.Trigger=EncounterTrigger.RoundInterval;periodic.RoundInterval=2;periodic.Weight=0;periodic.PriorityOnAppearance=true;
  d.Skills=new[]{d.Skills[0],periodic};g=Start(d);Check(g.EnemyShield==5,"round start boss passive executes after shield reset");g.EnemyHealth=60;Round(g);Check(g.Enemy.Encounter.PhaseIndex==1,"boss phase transition");Check(g.Timeline.Count(a=>a.EncounterSlot=="periodic")==1&&g.Enemy.Statuses[CardEffect.Invulnerable]==1,"zero-weight fixed trigger and priority appearance");
  int hp=g.EnemyHealth;CombatResolver.Damage(g.Player,g.Enemy,100);Check(g.EnemyHealth==hp,"appearance immunity blocks damage");g.Enemy.Statuses.EndRound();Check(g.Enemy.Statuses[CardEffect.Invulnerable]==0,"immunity expires at round end");
  var phaseAction=new BattleAction {Enemy=true,EncounterSlot="base",EncounterEffects=new[]{E(EncounterOperation.Shield,1)}};
  Call(g,"AfterContentAction",phaseAction,0);Call(g,"AfterContentAction",phaseAction,0);var queued=g.CaptureSave().Pending.Select(i=>g.CaptureSave().Actions[i]).Where(a=>a.IsNumberOnly).ToArray();Check(queued.Length==1&&queued[0].NumberCandidates.Length==6,"first-own-action passive once and wildcard candidates");
  // Restore all phase, special activation, pending composite effects and RNG state.
  var restored=ContainmentGame.RestoreSave(g.CaptureSave(),Setup(d));Check(restored.Enemy.Encounter.PhaseIndex==1&&restored.Enemy.ActiveRules.Count()==g.Enemy.ActiveRules.Count(),"save encounter phase and rules");Check(restored.CaptureSave().Pending.Length==g.CaptureSave().Pending.Length,"save pending actions");
  var locked=g.Timeline[0];locked.LockedPosition=true;Check(!g.InsertCard(g.Hand[0],0),"locked position blocks insertion");
  d=Definition();d.Skills=new[]{Skill("zero",E(EncounterOperation.Shield,1)),Skill("weighted",E(EncounterOperation.Shield,1))};d.Skills[0].Weight=0;g=Start(d);for(int i=0;i<100;i++)Check(((IEnumerable<BattleAction>)Call(g,"GenerateContentActions")).All(a=>a.EncounterSlot=="weighted"),"zero-weight skill never random draws");
  d=Definition();d.Rewards=new[]{new EncounterReward {Kind=1,Min=10,Max=10,Probability=100},new EncounterReward {Kind=1,Min=100,Max=100,Probability=0},new EncounterReward {Kind=2,Min=2,Max=2,ChoiceCount=3,CanSkip=true,Probability=100}};g=Start(d);Kill(g);Check(g.Coins==10&&g.Rewards.Count==3&&g.CanSkipReward,"configured probability and first card choice batch");var saved=ContainmentGame.RestoreSave(g.CaptureSave(),Setup(d));Check(saved.CanSkipReward&&saved.Rewards.Count==3,"save rewards and skip flag");int deck=g.Deck.Count;g.TakeReward(0);Check(g.Deck.Count==deck+1&&g.Phase==GamePhase.Reward,"multiple card rewards remain until consumed");Check(g.SkipReward()&&g.Phase==GamePhase.Map&&g.Rewards.Count==0,"skip completes reward batch");
  d=Definition(true);d.Rewards=new[]{new EncounterReward {Kind=2,Min=1,Max=1,ChoiceCount=3,CanSkip=true,Probability=100}};var s=Setup(d);var final=Definition(true);final.Id="final";final.LayerMin=final.LayerMax=2;s.BossEncounters.Add(final);g=new ContainmentGame(7,s);g.Victories=6;g.StartBattle(true);Kill(g);Check(g.Phase==GamePhase.Reward,"boss rewards presented before layer transition");g.SkipReward();Check(g.AdventureLayer==2&&g.Phase==GamePhase.Map,"first-layer boss advances adventure");g.StartBattle(true);Check(g.Enemy.Encounter.Definition.Id=="final","boss layer filter");Kill(g);Check(g.Phase==GamePhase.Won,"final layer boss completes game");
  d=Definition();g=Start(d);PlanForForecast(g);var rng=g.RandomState;int health=g.Health;var forecast=g.Forecast();Check(g.RandomState==rng&&g.Health==health,"forecast does not mutate encounter/RNG");Check(forecast!=null,"authored forecast resolves");
  d=Definition(true);d.Skills=new[]{Skill("start replay",E(EncounterOperation.LoseHealth,60)),special.Copy()};d.Phases=new[]{new EncounterPhase {Index=0,Passives=new[]{new EncounterPassive {Timing=EncounterTiming.RoundStart,Effects=new[]{E(EncounterOperation.RandomBasicSkill)}}}}};g=Start(d);
  Check(g.EnemyHealth==40&&g.EnemyShield==0&&g.Timeline.Count(a=>a.EncounterSlot=="threshold")==1,"round-start passive unlocks special for planning without executing it twice");
  d=Definition();d.ActionMin=d.ActionMax=1;d.Skills=new[]{Skill("ordered",E(EncounterOperation.RandomOwnSequence),E(EncounterOperation.Poison,10))};d.Sequences[0].Effects=new[]{E(EncounterOperation.Heal,1)};g=Start(d);g.EnemyHealth=50;Plan(g);g.Step();
  Check(g.Enemy.Statuses[CardEffect.Poison]==0,"queued own sequence precedes trailing poison");var continuation=ContainmentGame.RestoreSave(g.CaptureSave(),Setup(d));g.Step();continuation.Step();Check(g.EnemyHealth==51&&g.Enemy.Statuses[CardEffect.Poison]==0,"nested sequence resolves before next authored effect");g.Step();continuation.Step();Check(g.Enemy.Statuses[CardEffect.Poison]==10&&continuation.Enemy.Statuses[CardEffect.Poison]==10&&continuation.RandomState==g.RandomState,"ordered continuation and pending save restoration");
  d=Definition();var boosted=Setup(d);boosted.EnemyGrowthEnabled=true;boosted.EnemyGrowthLevelInterval=1;boosted.EnemyGrowthAmount=2;g=new ContainmentGame(17,boosted);g.ConfigureRoute(RouteGenerator.Generate(2));g.Route.Enter(g.Route.Graph.Nodes[0].id);g.Route.Complete();g.StartBattle();g.Enemy.Power=3;g.EnemyShield=0;g.EnemyHealth=50;
  action=new BattleAction {Enemy=true,EncounterEffects=new[]{E(EncounterOperation.Shield,4),E(EncounterOperation.Heal,4),E(EncounterOperation.Poison,2)}};Call(g,"ApplyEncounterEffects",action,action.EncounterEffects,BattleEventSource.EnemySkill);Check(g.EnemyShield==9&&g.EnemyHealth==59&&g.Enemy.Statuses[CardEffect.Poison]==7,"power and global growth apply once to shield, heal and status");
  action=new BattleAction {Enemy=true,EncounterEffects=new[]{E(EncounterOperation.LoseHealth,10)}};Call(g,"ApplyEncounterEffects",action,action.EncounterEffects,BattleEventSource.EnemySkill);Check(g.EnemyHealth==49,"direct health loss is not scaled as damage");
  Console.WriteLine("PASS: "+checks+" authored enemy/boss targeting, skills, phases, appearance, weights, rewards, layers, save and forecast assertions");
 }
 static void PlanForForecast(ContainmentGame game){game.AddCard(game.Hand[0]);}
}
